# -*- coding: utf-8 -*-
"""
Transportation model for a regional water authority.
Minimize total pumping cost while satisfying supply, demand and arc capacity limits.
"""

import pulp

# -------------------------------------------------------------------------
# Data
# -------------------------------------------------------------------------

# Reservoirs (supply nodes) and their capacities (million gallons)
supply = {
    "Alpha":    10,
    "Beta":     90,
    "Gamma":    65,
    "Delta":    91,
    "Epsilon":  46,
    "Zeta":     96,
    "Eta":      72,
    "Theta":    29,
}

# Distribution centers (demand nodes) and their required quantities (million gallons)
demand = {
    "Delta":    0,
    "Epsilon":  85,
    "Zeta":     65,
    "Eta":      60,
    "Theta":    85,
    "Iota":     86,
    "Kappa":    48,
    "Lambda":   70,
}

# Arc capacities (million gallons) and costs (cost per million gallons)
# Structure: capacities[reservoir][center] = capacity
#            costs[reservoir][center]      = unit cost
capacities = {
    "Alpha": {
        "Delta":   53, "Epsilon": 13, "Zeta": 59, "Eta": 10,
        "Theta":   10, "Iota":   16, "Kappa": 52, "Lambda": 5,
    },
    "Beta": {
        "Delta":   42, "Epsilon": 44, "Zeta": 12, "Eta": 5,
        "Theta":    9, "Iota":   84, "Kappa": 10, "Lambda": 24,
    },
    "Gamma": {
        "Delta":   81, "Epsilon": 26, "Zeta": 65, "Eta": 88,
        "Theta":   15, "Iota":   79, "Kappa": 22, "Lambda": 7,
    },
    "Delta": {
        "Delta":  100, "Epsilon": 76, "Zeta": 22, "Eta": 18,
        "Theta":  14, "Iota":   95, "Kappa": 13, "Lambda": 82,
    },
    "Epsilon": {
        "Delta":   89, "Epsilon": 19, "Zeta": 30, "Eta": 17,
        "Theta":   67, "Iota":   60, "Kappa": 15, "Lambda": 19,
    },
    "Zeta": {
        "Delta":   65, "Epsilon": 96, "Zeta": 62, "Eta": 69,
        "Theta":   98, "Iota":   26, "Kappa": 74, "Lambda": 18,
    },
    "Eta": {
        "Delta":   22, "Epsilon": 52, "Zeta": 98, "Eta": 59,
        "Theta":   70, "Iota":   21, "Kappa": 15, "Lambda": 85,
    },
    "Theta": {
        "Delta":   69, "Epsilon":  9, "Zeta": 98, "Eta": 75,
        "Theta":   36, "Iota":   17, "Kappa": 98, "Lambda": 53,
    },
}

costs = {
    "Alpha": {
        "Delta": 9, "Epsilon": 6, "Zeta": 5, "Eta": 7,
        "Theta":10, "Iota": 3, "Kappa": 6, "Lambda": 1,
    },
    "Beta": {
        "Delta": 7, "Epsilon": 8, "Zeta": 8, "Eta": 5,
        "Theta": 2, "Iota": 4, "Kappa": 6, "Lambda": 4,
    },
    "Gamma": {
        "Delta": 7, "Epsilon": 1, "Zeta":10, "Eta": 6,
        "Theta": 3, "Iota": 3, "Kappa": 8, "Lambda": 2,
    },
    "Delta": {
        "Delta": 2, "Epsilon": 3, "Zeta":10, "Eta": 1,
        "Theta": 4, "Iota": 3, "Kappa": 1, "Lambda": 9,
    },
    "Epsilon": {
        "Delta": 7, "Epsilon": 7, "Zeta": 3, "Eta": 5,
        "Theta": 7, "Iota": 8, "Kappa": 5, "Lambda": 9,
    },
    "Zeta": {
        "Delta": 1, "Epsilon": 3, "Zeta": 8, "Eta": 3,
        "Theta": 2, "Iota": 2, "Kappa": 8, "Lambda": 5,
    },
    "Eta": {
        "Delta": 5, "Epsilon": 5, "Zeta": 7, "Eta": 1,
        "Theta":10, "Iota": 5, "Kappa": 6, "Lambda": 8,
    },
    "Theta": {
        "Delta": 2, "Epsilon": 1, "Zeta": 5, "Eta": 4,
        "Theta": 8, "Iota": 5, "Kappa": 9, "Lambda": 4,
    },
}

reservoirs = list(supply.keys())
centers    = list(demand.keys())

# -------------------------------------------------------------------------
# Model
# -------------------------------------------------------------------------

model = pulp.LpProblem("Water_Distribution_MinCost", pulp.LpMinimize)

# Decision variables: flow from reservoir r to center c (million gallons)
flow = pulp.LpVariable.dicts(
    "x",
    ((r, c) for r in reservoirs for c in centers),
    lowBound=0,
    cat="Continuous"
)

# Objective: minimize total pumping cost
model += pulp.lpSum(costs[r][c] * flow[(r, c)] for r in reservoirs for c in centers)

# Supply constraints: total outflow from each reservoir ≤ its capacity
for r in reservoirs:
    model += (
        pulp.lpSum(flow[(r, c)] for c in centers) <= supply[r],
        f"Supply_{r}"
    )

# Demand constraints: total inflow to each center = its demand
for c in centers:
    model += (
        pulp.lpSum(flow[(r, c)] for r in reservoirs) == demand[c],
        f"Demand_{c}"
    )

# Arc capacity constraints
for r in reservoirs:
    for c in centers:
        model += (
            flow[(r, c)] <= capacities[r][c],
            f"Cap_{r}_{c}"
        )

# -------------------------------------------------------------------------
# Solve
# -------------------------------------------------------------------------

solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# -------------------------------------------------------------------------
# Output
# -------------------------------------------------------------------------

print("Status :", pulp.LpStatus[model.status])
print(f"Total minimum cost: {pulp.value(model.objective):.2f} (cost units)")

print("\nOptimal flows (million gallons):")
for r in reservoirs:
    for c in centers:
        qty = flow[(r, c)].varValue
        if qty is not None and qty > 1e-6:   # show only positive flows
            print(f"  {r} -> {c} : {qty:.2f}")

