# -*- coding: utf-8 -*-
"""
Transportation model: allocate electricity from plants to regional grids
to satisfy demand at minimum transmission cost.
"""

import pulp

# ---------- Data ----------
# Plant generation capacities (MW)
plant_capacity = {
    "Alpha":   0,
    "Beta":    7,
    "Gamma":   87,
    "Delta":   72,
    "Epsilon": 98,
    "Zeta":    23,
    "Eta":     70,
}

# Grid demands (MW)
grid_demand = {
    "Delta":   81,
    "Epsilon": 54,
    "Zeta":    53,
    "Eta":     22,
    "Theta":   97,
    "Iota":    10,
    "Kappa":   40,
}

# Transmission line capacities (MW) and unit costs ($/MW)
# structure: data[plant][grid] = (capacity, cost)
line_data = {
    "Alpha": {
        "Delta":   (100, 4), "Epsilon": (28, 8), "Zeta": (48, 5),
        "Eta":     (68, 5), "Theta": (34, 4), "Iota": (19, 1), "Kappa": (92, 8)
    },
    "Beta": {
        "Delta":   (54, 6), "Epsilon": (54, 9), "Zeta": (64, 6),
        "Eta":     (70, 2), "Theta": (64, 2), "Iota": (77, 5), "Kappa": (84,10)
    },
    "Gamma": {
        "Delta":   (33, 7), "Epsilon": (91, 4), "Zeta": (56, 6),
        "Eta":     (69, 7), "Theta": (44, 3), "Iota": (67, 4), "Kappa": (34,5)
    },
    "Delta": {
        "Delta":   (45, 4), "Epsilon": (71, 8), "Zeta": (92, 6),
        "Eta":     (5, 5),  "Theta": (16, 7), "Iota": (65,10), "Kappa": (45,3)
    },
    "Epsilon": {
        "Delta":   (55, 2), "Epsilon": (34, 7), "Zeta": (60, 6),
        "Eta":     (11, 9), "Theta": (78, 8), "Iota": (10,4), "Kappa": (57,6)
    },
    "Zeta": {
        "Delta":   (16, 6), "Epsilon": (38, 7), "Zeta": (30, 5),
        "Eta":     (97, 6), "Theta": (46, 7), "Iota": (27,5), "Kappa": (19,2)
    },
    "Eta": {
        "Delta":   (28, 8), "Epsilon": (94, 5), "Zeta": (51, 2),
        "Eta":     (8, 8),  "Theta": (34, 3), "Iota": (10,6), "Kappa": (6,4)
    },
}

plants = list(plant_capacity.keys())
grids  = list(grid_demand.keys())

# ---------- Model ----------
model = pulp.LpProblem("Electricity_Allocation", pulp.LpMinimize)

# Decision variables: flow from plant p to grid g (MW)
flow = {}
for p in plants:
    for g in grids:
        cap, _ = line_data[p][g]
        var = pulp.LpVariable(f"x_{p}_{g}", lowBound=0, upBound=cap, cat="Continuous")
        flow[(p, g)] = var

# Objective: minimize total transmission cost
model += pulp.lpSum(
    line_data[p][g][1] * flow[(p, g)] for p in plants for g in grids
), "Total_Transmission_Cost"

# Plant capacity constraints
for p in plants:
    model += (
        pulp.lpSum(flow[(p, g)] for g in grids) <= plant_capacity[p],
        f"PlantCapacity_{p}"
    )

# Grid demand constraints (must be met exactly)
for g in grids:
    model += (
        pulp.lpSum(flow[(p, g)] for p in plants) == grid_demand[g],
        f"Demand_{g}"
    )

# ---------- Solve ----------
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# ---------- Output ----------
print("Status:", pulp.LpStatus[model.status])
print(f"Total cost = ${pulp.value(model.objective):.2f}\n")

print("Optimal flows (MW):")
for p in plants:
    for g in grids:
        qty = flow[(p, g)].varValue
        # display only positive shipments for brevity
        if qty is not None and qty > 1e-5:
            print(f"  {p} -> {g}: {qty:.2f} MW")
